import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const d=JSON.parse('{"title":"Профили, друзья и союзы","description":"","frontmatter":{"pageId":"players/community","contentRevision":5},"headers":[],"relativePath":"ru/players/community.md","filePath":"ru/players/community.md"}'),i={name:"ru/players/community.md"};function l(n,a,s,c,p,u){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="профили-друзья-и-союзы" tabindex="-1">Профили, друзья и союзы <a class="header-anchor" href="#профили-друзья-и-союзы" aria-label="Permalink to &quot;Профили, друзья и союзы&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>В <strong>Игроки → Социальное</strong> отредактируй биографию, настройки приглашений и уведомлений. Найди игрока, отправь приглашение дружбы или создай/вступи в союз. Владелец союза приглашает участников, передаёт владение или распускает группу. Чат союза виден текущим участникам с момента вступления, не пересылается в Discord.</p><p>Казна принимает взносы из кошелька. Владелец назначает дневные лимиты вывода; расход считается за сутки UTC и не сбрасывается выходом/повторным вступлением. Уход не возвращает взнос; при роспуске весь остаток получает текущий владелец. Передавай владение осознанно.</p><p>Союзники защищены от взаимных вредных нападений и событий. Вступление при конфликтующей очереди может быть отклонено.</p><h2 id="social-consent" tabindex="-1">Профиль, приглашение и альянс: управление согласием <a class="header-anchor" href="#social-consent" aria-label="Permalink to &quot;Профиль, приглашение и альянс: управление согласием {#social-consent}&quot;">​</a></h2><p>«Players → Social» открывает каталог, включая offline. Отредактируй биографию и разрешение приглашений в своём профиле. Публичные поля включают последнюю активность и предпочтения — не записывай туда секреты.</p><p>Друг/член альянса появляется только после приглашения и принятия. Отправитель может отозвать, получатель — отказаться; закрытие приглашений отзывает ожидающие. Блокировка с любой стороны удаляет дружбу и ожидающие приглашения; unblock не восстанавливает согласие автоматически.</p><p>Владелец альянса приглашает, выдаёт лимиты казны, передаёт владение и распускает группу. Чтобы выйти владельцу, сначала передай владение или распусти. Союзники не могут атаковать друг друга harmful-действиями; вступление при незавершённой взаимной враждебной операции может быть отклонено. Существующая операция и escrow от выхода не исчезают.</p><h2 id="treasury" tabindex="-1">Казна: взнос не является личным депозитом <a class="header-anchor" href="#treasury" aria-label="Permalink to &quot;Казна: взнос не является личным депозитом {#treasury}&quot;">​</a></h2><p>В казну попадает только серебро кошелька. Физическое сначала внеси обычным способом. Вывод из казны зачисляет кошелёк участника; для стопок снова нужен обычный вывод и почта.</p><p>У каждого, включая владельца, есть право вывода и дневной UTC-лимит. Новичку право не выдаётся автоматически. Уход/возврат и изменение лимита не обнуляют уже израсходованное за день. Вклад не создаёт права на его возврат: при выходе автоматической компенсации нет, а при роспуске <strong>весь баланс получает текущий владелец</strong>.</p><p>Казна учитывается в богатстве владельца ровно один раз. Вывод и передача владения с ненулевым балансом проверяют долг/freeze/угрозу всех текущих участников; блокировка между владельцем и членом тоже мешает выводу. При неизвестном ответе дождись исходного outbox-повтора. История последних 100 действий помогает сверить, что произошло; не повторяй перевод вручную.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Биография 500 символов; каталог до 200 игроков, 100 друзей, 16 членов союза, один союз на игрока. Приглашения 7 дней, до 32 входящих/исходящих. Транзакция до 1 млрд, казна до 1 трлн. Заморозка/долг/угроза участников может запрещать вывод.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./chat-pings">Чат, сообщения и пинги</a></li><li><a href="./guild-influence">Влияние гильдий</a></li><li><a href="./economy">Кошелёк, почта и рынок</a></li></ul>',18)])])}const m=e(i,[["render",l]]);export{d as __pageData,m as default};
